from pathlib import Path

from app.services import users

_DATA_DIR = Path(__file__).resolve().parents[2] / "data"


def _resolve_data_dir(value: object) -> Path | None:
    """Resolve an untrusted relative directory path inside the project data dir.

    Returns ``None`` when *value* is not a string or contains an empty, ``.``
    or ``..`` segment (an empty string selects the data directory itself).
    """
    if not isinstance(value, str):
        return None
    segments = [] if value == "" else value.split("/")
    if any(segment in ("", ".", "..") for segment in segments):
        return None
    base = _DATA_DIR.resolve()
    target = base.joinpath(*segments)
    try:
        target.resolve().relative_to(base)
    except ValueError:
        return None
    return target


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_data_manifest(params: dict) -> tuple[int, dict]:
    target = _resolve_data_dir(params.get("dir", ""))
    if target is None:
        return 400, {"error": "invalid path"}
    if not target.is_dir():
        return 404, {"error": "not found"}
    entries = [
        {"path": path.relative_to(target).as_posix(), "bytes": path.stat().st_size}
        for path in target.rglob("*")
        if path.is_file()
    ]
    entries.sort(key=lambda entry: entry["path"])
    return 200, {"entries": entries}
